    private string trackingNumber = "";
    private string errorMessage = "";
    private Shipment? trackedShipment;
    private List<Shipment> myShipments = [];
    private bool isLoadingMine = true;

    [CascadingParameter]
    private Task<AuthenticationState>? AuthState { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadMyShipments();
    }

    private async Task LoadMyShipments()
    {
        isLoadingMine = true;
        if (AuthState is not null)
        {
            var state = await AuthState;
            var email = state.User.Identity?.Name ?? "";
            myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
        }
        isLoadingMine = false;
    }

    private async Task SearchByTracking()
    {
        errorMessage = "";
        trackedShipment = null;

        if (string.IsNullOrWhiteSpace(trackingNumber))
        {
            errorMessage = "Please enter a tracking number.";
            return;
        }

        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
        if (trackedShipment is null)
        {
            errorMessage = $"No shipment found with tracking number '{trackingNumber}'.";
        }
    }

    private void SelectShipment(Shipment shipment)
    {
        trackedShipment = shipment;
        trackingNumber = shipment.TrackingNumber;
        errorMessage = "";
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
        {
            await SearchByTracking();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };

    private static string GetStatusDescription(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Your shipment is being prepared for dispatch.",
        ShipmentStatus.InTransit => "Your shipment is on its way.",
        ShipmentStatus.OutForDelivery => "Your shipment is out for delivery today!",
        ShipmentStatus.Delivered => "Your shipment has been delivered.",
        ShipmentStatus.Delayed => "Your shipment has been delayed. We apologize for the inconvenience.",
        _ => "Unknown status."
    };
}
