@page "/shipments"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="mb-3 d-flex gap-2 align-items-center">
    <label for="statusFilter" class="form-label mb-0">Filter by status:</label>
    <select id="statusFilter" class="form-select w-auto" @bind="selectedStatus">
        <option value="">All</option>
        @foreach (var status in Enum.GetValues<ShipmentStatus>())
        {
            <option value="@status">@status</option>
        }
    </select>
    <button class="btn btn-sm btn-outline-secondary" @onclick="LoadShipments">Refresh</button>
    <button class="btn btn-sm btn-primary" @onclick="ShowCreateForm">+ New Shipment</button>
</div>

@if (showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
            </div>
            <div class="mt-2">
                <button class="btn btn-success btn-sm" @onclick="CreateShipment">Create</button>
                <button class="btn btn-secondary btn-sm" @onclick="() => showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else if (FilteredShipments.Count == 0)
{
    <p>No shipments found.</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Customer</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.CustomerEmail</td>
                    <td>
                        <select class="form-select form-select-sm w-auto d-inline-block"
                                value="@shipment.Status"
                                @onchange="(e) => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment> shipments = [];
    private bool isLoading = true;
    private string selectedStatus = "";
    private bool showCreateForm;
    private Shipment newShipment = new();

    private List<Shipment> FilteredShipments => string.IsNullOrEmpty(selectedStatus)
        ? shipments
        : shipments.Where(s => s.Status.ToString() == selectedStatus).ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        isLoading = false;
    }

    private void ShowCreateForm()
    {
        newShipment = new Shipment();
        showCreateForm = true;
    }

    private async Task CreateShipment()
    {
        newShipment.TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpper()}";
        newShipment.Status = ShipmentStatus.Pending;
        newShipment.ShippedDate = DateTime.UtcNow;
        newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(7);
        await ShipmentService.CreateShipmentAsync(newShipment);
        showCreateForm = false;
        await LoadShipments();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            await LoadShipments();
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="mb-4">
    <div class="input-group" style="max-width: 500px;">
        <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-ABC12345)"
               @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
        <button class="btn btn-primary" @onclick="SearchByTracking">Track</button>
    </div>
</div>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-warning">@errorMessage</div>
}

@if (trackedShipment is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>@trackedShipment.TrackingNumber</strong>
            <span class="badge @GetStatusBadgeClass(trackedShipment.Status)">@trackedShipment.Status</span>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-5">Description</dt>
                <dd class="col-sm-7">@trackedShipment.Description</dd>

                <dt class="col-sm-5">Origin</dt>
                <dd class="col-sm-7">@trackedShipment.Origin</dd>

                <dt class="col-sm-5">Destination</dt>
                <dd class="col-sm-7">@trackedShipment.Destination</dd>

                <dt class="col-sm-5">Shipped Date</dt>
                <dd class="col-sm-7">@trackedShipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>

                <dt class="col-sm-5">Estimated Delivery</dt>
                <dd class="col-sm-7">
                    <strong>@trackedShipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</strong>
                    @if (trackedShipment.Status != ShipmentStatus.Delivered)
                    {
                        var daysLeft = (trackedShipment.EstimatedDelivery - DateTime.UtcNow).Days;
                        <span class="text-muted ms-2">
                            (@(daysLeft > 0 ? $"{daysLeft} days remaining" : "Arriving soon"))
                        </span>
                    }
                </dd>

                <dt class="col-sm-5">Status</dt>
                <dd class="col-sm-7">
                    @GetStatusDescription(trackedShipment.Status)
                </dd>
            </dl>
        </div>
    </div>
}

<hr class="my-4" />

<h3>My Shipments</h3>
<button class="btn btn-outline-secondary btn-sm mb-3" @onclick="LoadMyShipments">Refresh</button>

@if (isLoadingMine)
{
    <p><em>Loading your shipments...</em></p>
}
else if (myShipments.Count == 0)
{
    <p>No shipments found for your account.</p>
}
else
{
    <div class="list-group" style="max-width: 600px;">
        @foreach (var shipment in myShipments)
        {
            <button class="list-group-item list-group-item-action d-flex justify-content-between align-items-center"
                    @onclick="() => SelectShipment(shipment)">
                <div>
                    <strong>@shipment.TrackingNumber</strong>
                    <br />
                    <small class="text-muted">@shipment.Origin → @shipment.Destination</small>
                </div>
                <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
            </button>
        }
    </div>
}

@code {
    private string trackingNumber = "";
    private string errorMessage = "";
    private Shipment? trackedShipment;
    private List<Shipment> myShipments = [];
